import numpy as np
def compute_metrics(y_true, y_pred):
    y_true, y_pred = np.array(y_true), np.array(y_pred)
    tp = np.sum((y_true==1)&(y_pred==1))
    fp = np.sum((y_true==0)&(y_pred==1))
    fn = np.sum((y_true==1)&(y_pred==0))
    acc = np.mean(y_true==y_pred)
    prec = tp/(tp+fp) if (tp+fp)>0 else 0
    rec = tp/(tp+fn) if (tp+fn)>0 else 0
    f1 = 2*prec*rec/(prec+rec) if (prec+rec)>0 else 0
    return {'accuracy': round(float(acc),4), 'precision': round(float(prec),4), 'recall': round(float(rec),4), 'f1': round(float(f1),4)}
def build_confusion_matrix(y_true, y_pred, labels):
    y_true, y_pred = np.array(y_true), np.array(y_pred)
    n = len(labels)
    mat = np.zeros((n,n), dtype=int)
    for t,p in zip(y_true,y_pred):
        mat[t][p] += 1
    return {'labels': labels, 'matrix': mat.tolist()}
def detect_drift(reference, current, threshold=0.1):
    ref_mean = np.mean(reference); cur_mean = np.mean(current)
    diff = abs(ref_mean - cur_mean) / (abs(ref_mean)+1e-10)
    return {'drift_detected': diff > threshold, 'diff': round(float(diff),4), 'threshold': threshold}

import re
def preprocess(text):
    text=text.lower()
    text=re.sub(r"[^a-z0-9\s]","",text)
    return text
def extract_features(text):
    words=text.split()
    pos_words=["good","great","excellent","happy","love","thank"]
    neg_words=["bad","terrible","angry","slow","broken","hate"]
    pos=sum(1 for w in words if w in pos_words)
    neg=sum(1 for w in words if w in neg_words)
    return {"pos_count":pos,"neg_count":neg,"total":len(words)}
def classify_sentiment(features):
    ratio=features["pos_count"]/(features["neg_count"]+1)
    if ratio>=3:return "positive"
    if ratio>=0.5:return "neutral"
    return "negative"
def route_by_sentiment(sent):
    routes={"positive":"auto_reply","neutral":"general_queue","negative":"priority_agent"}
    return routes.get(sent,"general_queue")

import re
def check_style(code):
  issues=[]
  for i,line in enumerate(code.split("\n"),1):
    if len(line)>80:issues.append("Line "+str(i)+": too long ("+str(len(line))+" chars)")
    if "  " in line.rstrip():issues.append("Line "+str(i)+": double spaces")
    if line.endswith(" "):issues.append("Line "+str(i)+": trailing space")
  return issues
def detect_bugs(code):
  bugs=[]
  if "==" in code:
    bugs.append("Use is instead of ==");
  return bugs
def cyclomatic_complexity(code):
  return code.count("if")+code.count("for")+code.count("while")+1

def decompose_task(task,capabilities):
    steps=[]
    if "data" in task.lower():steps.append("fetch_data")
    if "analy" in task.lower():steps.append("analyze")
    if "report" in task.lower() or "summar" in task.lower():steps.append("generate_report")
    if "plot" in task.lower() or "chart" in task.lower():steps.append("visualize")
    if not steps:steps.append("process")
    return steps
def assign_subtasks(subtasks,agents):
    assignment={}
    for st in subtasks:
        best=None;best_score=-1
        for a_name,skills in agents.items():
            if st in skills["can_do"] and skills["workload"]>best_score:
                best=a_name;best_score=skills["workload"]
        if best:
            assignment[st]=best
            agents[best]["workload"]-=1
        else:assignment[st]="unassigned"
    return assignment

