import math
def compute_metrics(y_true,y_pred):
    n=len(y_true);errors=[t-p for t,p in zip(y_true,y_pred)]
    mse=sum(e*e for e in errors)/n
    return {"mse":round(mse,4),"rmse":round(math.sqrt(mse),4),"mae":round(sum(abs(e)for e in errors)/n,4)}
